(function(T,F){var D=window.SCD||{};for(var k in D)T=T.split("__"+k+"__").join(D[k]);var el=document.getElementById("sc");el.innerHTML=T+F;var ss=[].slice.call(el.querySelectorAll("script"));(function run(i){if(i>=ss.length)return;var o=ss[i],n=document.createElement("script");for(var a=0;a<o.attributes.length;a++)n.setAttribute(o.attributes[a].name,o.attributes[a].value);if(o.src){n.onload=n.onerror=function(){run(i+1)};o.parentNode.replaceChild(n,o)}else{n.text=o.text;o.parentNode.replaceChild(n,o);run(i+1)}})(0)})("<style>.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}#al{color:var(--text-primary,#1d1b19)}#al .steps{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;font-size:12px}#al .st{padding:4px 10px;border-radius:999px;background:var(--surface-1,#f1efeb);color:var(--text-muted,#8a847d)}#al .st.d{background:#e3f3ea;color:#1f7a4d}#al .st.n{background:#fbe8e0;color:#b4421b;font-weight:500}#al h3{font-size:18px;font-weight:500;margin:0 0 4px}#al .ds{font-size:14px;color:var(--text-secondary,#6b6660);margin:0 0 12px;line-height:1.6}#al button{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}#al .grp{font-size:13px;font-weight:500;color:#b4421b;margin:14px 0 6px}#al .row{display:flex;align-items:center;gap:10px;padding:8px 10px;margin:0 0 6px;border-radius:12px;border:2px solid #d9d5cf}#al .row.on{border-color:#e8663a;background:rgba(232,102,58,.10)}#al .play{flex:none;width:38px;height:38px;border-radius:50%;border:0;background:#e8663a;color:#fff;font-size:15px;display:flex;align-items:center;justify-content:center}#al .play.ing{background:#1d1b19}#al .pick{flex:1;min-width:0;text-align:left;border:0;background:transparent;padding:0}#al .pick b{display:block;font-size:14px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}#al .pick small{display:block;font-size:12px;color:var(--text-secondary,#6b6660);margin-top:2px}#al .tag{font-size:11px;padding:2px 7px;border-radius:999px;background:#fbe8e0;color:#b4421b;margin-left:6px;vertical-align:1px}#al .lv{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0 4px}#al .lv button{padding:6px 12px;border-radius:999px;border:1.5px solid #d9d5cf;background:transparent;font-size:13px}#al .lv button.on{border-color:#e8663a;background:#e8663a;color:#fff}#al .err{font-size:13px;color:#c0392b;min-height:18px;margin:6px 0 0}#al .rf{margin-top:4px;padding:11px 14px;border-radius:10px;border:1.5px solid #d9d5cf;background:transparent;font-size:14px}#al .go{margin-top:4px;padding:12px 18px;border-radius:10px;border:2px solid #e8663a;background:#e8663a;color:#fff;font-weight:500}@media (prefers-color-scheme:dark){#al .row,#al .lv button,#al .rf{border-color:#4a4642}#al .play.ing{background:#f1efeb;color:#1d1b19}#al .st.d{background:#173326;color:#6fd19c}#al .st.n{background:#3a2219;color:#f0794d}#al .tag{background:#3a2219;color:#f0794d}}</style>\n<h2 class=\"sr-only\">从 Artlist 清单挑一首音乐：每首可以试听，选好按用这首配我的片</h2>\n<div id=\"al\">\n<div class=\"steps\"><span class=\"st d\">✓ 导入</span><span class=\"st d\">✓ 粗剪</span><span class=\"st d\">✓ 字幕</span><span class=\"st d\">✓ 画面</span><span class=\"st d\">✓ 音效</span><span class=\"st n\">→ 音乐</span><span class=\"st\">出片</span></div>\n<h3>Artlist 推荐的 15 首：听完挑一首</h3>\n<p class=\"ds\" id=\"DS\">先在上面 Artlist 的清单按 ▶ 试听（顺序、编号跟这里一样），喜欢哪首就在这里点它。选好我会把它配进你的片（从副歌那段开始），出预览给你听。</p>\n<div id=\"L\"></div>\n<p style=\"margin:12px 0 0;font-size:13px;color:var(--text-secondary,#6b6660)\">音乐大小声</p>\n<div class=\"lv\" id=\"LV\"></div>\n<p class=\"err\" id=\"err\" role=\"alert\"></p>\n<div style=\"display:flex;gap:8px;flex-wrap:wrap;align-items:center\"><button type=\"button\" class=\"go\" id=\"go\">用这首配我的片 ↗</button><button type=\"button\" class=\"rf\" id=\"rf\"><span aria-hidden=\"true\">⟳</span> 都不喜欢，换一批</button></div>\n<audio id=\"AU\" preload=\"none\"></audio>\n</div>\n<script>(function(){\nvar ROWS=__ROWS__, lv=__LEVEL__, sel=null, playing=null, au=document.getElementById('AU');\nfunction esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/\"/g,'&quot;')}\nfunction draw(){var h='',g=null;\nROWS.forEach(function(r,i){if(r.style!==g){g=r.style;h+='<p class=\"grp\">'+esc(g)+'</p>'}\nh+='<div class=\"row'+(sel===i?' on':'')+'\">'+(r.au?'<button type=\"button\" class=\"play'+(playing===i?' ing':'')+'\" data-play=\"'+i+'\" aria-label=\"试听 '+esc(r.title)+'\">'+(playing===i?'❚❚':'▶')+'</button>':'')+\n'<button type=\"button\" class=\"pick\" data-sel=\"'+i+'\"><b>'+(i+1)+'. '+esc(r.title)+(r.rec?'<span class=\"tag\">已出预览</span>':'')+'</b><small>'+esc(r.artist)+(r.bpm?' · '+esc(r.bpm)+' BPM':'')+(r.dur?' · '+esc(r.dur):'')+'</small></button></div>'});\ndocument.getElementById('L').innerHTML=h;\ndocument.getElementById('LV').innerHTML=['-6','-3','0','+3','+6'].map(function(v){return '<button type=\"button\" data-lv=\"'+v+'\" class=\"'+(v===lv?'on':'')+'\">'+(v==='0'?'0':v+' dB')+'</button>'}).join('')}\nau.addEventListener('ended',function(){playing=null;draw()});\ndocument.getElementById('al').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;\nif(b.dataset.play){var i=+b.dataset.play;if(playing===i){au.pause();playing=null}else{au.src=ROWS[i].au;au.play();playing=i;sel=i}}\nelse if(b.dataset.sel){sel=+b.dataset.sel}\nelse if(b.dataset.lv){lv=b.dataset.lv}\nelse if(b.id==='rf'){au.pause();scSend('Artlist 这批都不喜欢，换一批（重新搜）');return}\nelse if(b.id==='go'){if(sel===null){document.getElementById('err').textContent='还没选歌：点歌名，出现橘色框就是选到了';return}\nau.pause();var r=ROWS[sel];scSend('音乐用 Artlist 清单的「'+r.title+'」— '+r.artist+'（songId '+r.id+'）'+(lv!=='0'?'，音乐 '+lv+' dB':''));return}\ndocument.getElementById('err').textContent='';draw()});\nif(ROWS.some(function(r){return r.au}))document.getElementById('DS').textContent='按 ▶ 听副歌那 10 秒，点歌名选这首。选好我会把它配进你的片（从副歌那段开始），出预览给你听。';\ndraw()})();</script>\n","<p class=\"sc-foot\" style=\"margin:8px 2px 0;font-size:12px;color:var(--text-muted,#8a847d)\">按了没反应？等我停下来再按，或直接在对话框打按钮上的字。</p><script>(function(){if(window.scSend&&window.scSend.ok)return;function B(t,f){var e=document.getElementById('sc-fb');if(!e){e=document.createElement('details');e.id='sc-fb';e.style.cssText='margin:10px 2px 0;padding:8px 12px;border-radius:10px;font-size:12.5px;line-height:1.6;border:1px solid #e8663a66;background:#e8663a12;color:inherit';var o=document.querySelector('.sc-foot');o?o.parentNode.insertBefore(e,o):document.body.appendChild(e)}var s=t.length>40?t.slice(0,40)+'…':t;e.innerHTML='<summary style=\"cursor:pointer\">'+(f?'<b>这个按钮没送出去</b> · 点这里看怎么办':'已送出：「'+s.replace(/</g,'&lt;')+'」· 对话框没出现？点这里')+'</summary><div>Claude 还在跑时按钮会没反应。等它停下来再按，或复制这句贴到对话框送出：</div><textarea readonly rows=\"2\" style=\"display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:6px 8px;border-radius:8px;border:1px solid #d9d5cf;font:inherit;background:transparent;color:inherit\"></textarea><button type=\"button\" style=\"margin-top:6px;padding:4px 12px;border-radius:8px;border:1px solid #d9d5cf;background:transparent;color:inherit;font:inherit;cursor:pointer\">复制这句</button>';var a=e.querySelector('textarea'),b=e.querySelector('button');a.value=t;b.onclick=function(v){v.preventDefault();a.focus();a.select();var k=0;try{k=document.execCommand('copy')}catch(x){}try{navigator.clipboard&&(navigator.clipboard.writeText(t),k=1)}catch(x){}b.textContent=k?'已复制，贴到对话框送出':'已选取，按 ⌘C / Ctrl+C 复制'};if(f)e.open=true}window.scSend=function(t){t=String(t==null?'':t);var f=0;try{if(typeof sendPrompt!='function')f=1;else{var r=sendPrompt(t);r&&r.then&&r.then(null,function(){B(t,1)})}}catch(x){f=1}B(t,f)};window.scSend.ok=1})();</script>");